const tasks = $input.first().json.data || [];
const task = tasks[0] || null;
return [{ json: { task_id: task?.id || null, user_id: task?.user_id || null } }];

// Aggregate all data and calculate KPI scores
const hr = $('Fetch HR Stats').first().json?.stats || {};
const fin = $('Fetch Finance Summary').first().json || {};
const sup = $('Fetch Support Report').first().json?.report || {};
const taskCtx = $('Extract Analytics Task').first().json;

// Calculate sub-scores
const hrScore = hr.total > 0
  ? Math.round(((hr.shortlisted || 0) / hr.total) * 100)
  : 0;

const finScore = fin.record_count > 0
  ? Math.max(0, 100 - Math.round(((fin.anomaly_count || 0) / fin.record_count) * 100))
  : 100;

const supScore = sup.total > 0
  ? Math.round(((sup.resolved || 0) / sup.total) * 100)
  : 0;

const overallScore = Math.round((hrScore + finScore + supScore) / 3);

const rating =
  overallScore >= 80 ? 'excellent' :
  overallScore >= 60 ? 'good' :
  overallScore >= 40 ? 'average' : 'poor';

const kpiSnapshot = {
  'HR Shortlist Rate': `${hrScore}%`,
  'Finance Health': `${finScore}%`,
  'Support Resolution Rate': `${supScore}%`,
  'Total CV Screenings': hr.total || 0,
  'Total Transactions': fin.record_count || 0,
  'Finance Anomalies': fin.anomaly_count || 0,
  'Total Tickets': sup.total || 0,
  'Tickets Escalated': sup.escalated || 0,
};

const prompt = `You are an enterprise analytics AI. Generate a concise weekly KPI analysis based on this data:

HR: ${hr.total || 0} CVs screened, ${hr.shortlisted || 0} shortlisted (${hrScore}% rate), ${hr.rejected || 0} rejected
Finance: ${fin.record_count || 0} transactions, ৳${Number(fin.total_spend || 0).toLocaleString()} total spend, ${fin.anomaly_count || 0} anomalies detected (health score: ${finScore}%)
Support: ${sup.total || 0} tickets, ${sup.resolved || 0} resolved (${supScore}% resolution rate), ${sup.escalated || 0} escalated
Overall Score: ${overallScore}/100 (${rating})

Provide: 1) Key insights (2-3 sentences), 2) Three specific action items for the upcoming week. Be data-driven and concise.`;

return [{
  json: {
    overall_score: overallScore,
    performance_rating: rating,
    kpi_snapshot: kpiSnapshot,
    prompt,
    task_id: taskCtx.task_id,
    user_id: taskCtx.user_id
  }
}];

// Extract Gemini insights and parse action items
const geminiRes = $input.first().json;
const fullText = geminiRes?.candidates?.[0]?.content?.parts?.[0]?.text || '';
const kpiCtx = $('Calculate KPI Scores').first().json;

// Extract action items (lines starting with a number or bullet)
const lines = fullText.split('\n').filter(l => l.trim());
const actionItems = lines
  .filter(l => /^(\d+[.)]|[-*•])/.test(l.trim()))
  .map(l => l.replace(/^(\d+[.)]|[-*•])\s*/, '').trim())
  .slice(0, 3);

// First paragraph = insights
const insightsParagraph = lines.find(l => l.length > 50 && !/^(\d+[.)]|[-*•])/.test(l.trim())) || fullText.substring(0, 300);

return [{
  json: {
    user_id: kpiCtx.user_id,
    task_id: kpiCtx.task_id,
    performance_rating: kpiCtx.performance_rating,
    overall_score: kpiCtx.overall_score,
    ai_insights: insightsParagraph,
    action_items: actionItems.length > 0 ? actionItems : ['Review anomaly flagged transactions', 'Follow up with shortlisted candidates', 'Resolve escalated support tickets'],
    kpi_snapshot: kpiCtx.kpi_snapshot
  }
}];
